const fs = require('fs');
const vm = require('vm');

const ANCHOR = 'let input = "19/20";';

function run() {
  let inputs;
  try {
    inputs = JSON.parse(fs.readFileSync('inputs.json', 'utf8'));
    if (!Array.isArray(inputs)) throw new Error('inputs.json is not an array');
  } catch (e) {
    return { results: [], harness_error: 'failed to read inputs.json: ' + String((e && e.message) || e) };
  }

  let src;
  try {
    src = fs.readFileSync('block-0.txt', 'utf8');
  } catch (e) {
    return { results: [], harness_error: 'failed to read block-0.txt: ' + String((e && e.message) || e) };
  }

  if (src.split(ANCHOR).length !== 2) {
    return { results: [], harness_error: 'input anchor not found exactly once in block-0.txt' };
  }

  const results = [];
  for (const item of inputs) {
    const id = item && item.id;
    try {
      const code = src.replace(ANCHOR, () => 'let input = ' + JSON.stringify(item.input) + ';') +
        '\n;[firstValue, secondValue];';
      const quiet = () => {};
      const sandbox = { console: { log: quiet, info: quiet, warn: quiet, error: quiet } };
      const ctx = vm.createContext(sandbox);
      const val = vm.runInContext(code, ctx, { timeout: 5000, filename: 'candidate.js' });
      results.push({ id: id, actual: JSON.parse(JSON.stringify(Array.from(val))) });
    } catch (e) {
      results.push({ id: id, error: String((e && e.message) || e) });
    }
  }
  return { results: results };
}

try {
  process.stdout.write(JSON.stringify(run()) + '\n');
} catch (e) {
  process.stdout.write(JSON.stringify({ results: [], harness_error: String((e && e.message) || e) }) + '\n');
}

const fs = require('fs');
const path = require('path');
const vm = require('vm');

function finish(obj) {
  process.stdout.write(JSON.stringify(obj));
}

function main() {
  let ts;
  let cases;
  let src;
  try {
    ts = require('typescript');
  } catch (e) {
    return finish({ results: [], harness_error: 'typescript not available: ' + String(e) });
  }
  try {
    cases = JSON.parse(fs.readFileSync(path.join(__dirname, 'inputs.json'), 'utf8'));
    src = fs.readFileSync(path.join(__dirname, 'block-1.txt'), 'utf8');
  } catch (e) {
    return finish({ results: [], harness_error: 'read failure: ' + String(e) });
  }
  if (!Array.isArray(cases)) {
    return finish({ results: [], harness_error: 'inputs.json is not an array' });
  }
  // Input binding anchor: exact literal demo assignment in block-1 (input binding only).
  const anchor = 'const input = "19/20";';
  if (src.indexOf(anchor) < 0) {
    return finish({ results: [], harness_error: 'input binding anchor not found in block-1' });
  }
  const results = [];
  for (const c of cases) {
    const bound = src.replace(anchor, 'const input = ' + JSON.stringify(c.input) + ';');
    const lines = [];
    try {
      const js = ts.transpileModule(bound, {
        compilerOptions: { target: ts.ScriptTarget.ES2019, module: ts.ModuleKind.None }
      }).outputText;
      const sandbox = {
        console: {
          log: function () {
            lines.push(Array.prototype.slice.call(arguments).map(String).join(' '));
          }
        }
      };
      vm.createContext(sandbox);
      vm.runInContext(js, sandbox, { timeout: 5000 });
      results.push({ id: c.id, actual: lines.slice() });
    } catch (e) {
      results.push({ id: c.id, error: String(e && e.message ? e.message : e) });
    }
  }
  finish({ results: results });
}

main();
